<script lang="ts">
 import {onDestroy} from 'svelte';
 import {invoke} from '@tauri-apps/api/core';
 import FormattingToolbar from './FormattingToolbar.svelte';
 import {continueList} from './continue-list';
 import {draftError,recipients,mailContent,type MailDraft} from './mail-drafts';
 let {draft,ownId,permitted,onChange,onClose,onAccepted,onDiscard}:{draft:MailDraft;ownId:string;permitted:boolean;onChange:(d:MailDraft)=>boolean;onClose:()=>void;onAccepted:(id:string)=>void;onDiscard:(id:string)=>void}=$props();
 let input=$state<HTMLTextAreaElement>(),busy=$state(false),review=$state(false),error=$state(''),confirmDiscard=$state(false),alive=true;
 let lookup=$state(''),target=$state<'to'|'cc'|'bcc'>('to'),people=$state<{id:string;displayName:string;mail?:string;userPrincipalName?:string}[]>([]),searching=$state(false);let serial=0;
 const invalid=$derived(draftError(draft));
 function edit(patch:Partial<MailDraft>){review=false;error='';onChange({...draft,...patch,updated:Date.now()});}
 async function find(){const query=lookup.trim();if(query.length<2)return;const n=++serial;searching=true;try{const result=await invoke<{value:typeof people}>('graph_search_users',{query});if(alive&&n===serial)people=result.value??[];}catch{if(alive&&n===serial)error='Coworker search unavailable. You can enter a full email address.';}finally{if(alive&&n===serial)searching=false;}}
 async function send(){if(busy||draft.uncertain||invalid||!permitted)return;busy=true;error='';review=false;const id=draft.id,attemptId=crypto.randomUUID();
  // Persist the uncertain marker before IPC: a crash or navigation must never enable a blind retry.
  if(!onChange({...draft,attemptId,uncertain:true,updated:Date.now()})){busy=false;error='Draft could not be saved. Sending was stopped.';return;}
  try{const result=await invoke<{status:string;error?:string}>('mail_send_new',{ownId,draft:{to:recipients(draft.to),cc:recipients(draft.cc),bcc:recipients(draft.bcc),subject:draft.subject,content:mailContent(draft),action:draft.action,sourceId:draft.sourceId,contentType:draft.formatted?'HTML':'Text',attemptId}});if(result.status==='accepted'){onAccepted(id);}else if(alive)error=result.error??'Sending was not confirmed. Check Sent in Outlook.';}catch{if(alive)error='Sending was not confirmed. Check Sent in Outlook before trying again.';}finally{if(alive)busy=false;}
 }
 onDestroy(()=>{alive=false;++serial;});
</script>
<section class="mail-compose" aria-label="New email composer">
 <header><div><span class="eyebrow">{draft.action==='replyAll'?'REPLY ALL':draft.action==='reply'?'REPLY':draft.action==='forward'?'FORWARD':'NEW EMAIL'}</span><h2>A little more signal.</h2></div><button disabled={busy} onclick={onClose}>Save & close</button></header>
 <p class="note">Draft saved on this Mac · Enter adds a line · only Send sends email</p>
 {#if !permitted}<p role="status">Sending needs Mail.Send consent and a fresh sign-in. You can still save a draft.</p>{/if}
 {#if draft.context}<details><summary>Original message included</summary><pre style="white-space:pre-wrap;max-height:220px;overflow:auto;font-size:12px">{draft.context}</pre></details>{/if}
 {#if draft.action==='forward'}<p class="note">Forward includes the original message and its attachments. Review recipients carefully.</p>{/if}
 <fieldset disabled={busy||draft.uncertain}>
 {#each ['to','cc','bcc'] as field}<label class="address">{field==='to'?'To':field==='cc'?'Cc':'Bcc'}<input aria-label={field==='to'?'To':field==='cc'?'Cc':'Bcc'} value={draft[field as 'to'|'cc'|'bcc']} placeholder="name@example.com" onfocus={()=>target=field as 'to'|'cc'|'bcc'} oninput={e=>edit({[field]:e.currentTarget.value})}/></label>{/each}
 <details><summary>Find a coworker</summary><div class="lookup"><select aria-label="Add coworker to" bind:value={target}><option value="to">To</option><option value="cc">Cc</option><option value="bcc">Bcc</option></select><input aria-label="Find email recipient" bind:value={lookup} placeholder="Search by name" onkeydown={e=>{if(e.key==='Enter'){e.preventDefault();void find();}}}/><button disabled={searching||lookup.trim().length<2} onclick={find}>Search people</button></div>{#each people as person(person.id)}{@const email=person.mail||person.userPrincipalName}{#if email}<button class="person" onclick={()=>{edit({[target]:[draft[target],email].filter(Boolean).join('; ')});people=[];lookup='';}}>{person.displayName} · {email}</button>{/if}{/each}</details>
 <label>Subject<input aria-label="Email subject" value={draft.subject} maxlength="1000" oninput={e=>edit({subject:e.currentTarget.value})}/></label>
 <FormattingToolbar showSizeWarning={false} text={draft.text} formatted={draft.formatted} {input} onText={text=>edit({text})} onFormat={formatted=>edit({formatted})}/>
 <textarea bind:this={input} use:continueList={{formatted:draft.formatted,onText:text=>edit({text})}} aria-label="Email message" value={draft.text} oninput={e=>edit({text:e.currentTarget.value})} placeholder="Write your message…" rows="12"></textarea>
 </fieldset>
 {#if error}<p role="alert" class="error">{error}</p>{/if}
 {#if draft.uncertain}<div class="uncertain" role="status">This draft has a send attempt with an unconfirmed result. Check Sent in Outlook. TAUT will not resend automatically.<button disabled={busy} onclick={()=>{if(onChange({...draft,uncertain:false,attemptId:undefined,updated:Date.now()}))error='';}}>I checked Outlook — unlock draft</button></div>{/if}
 {#if review}<div class="review" role="group" aria-label="Review email before sending"><strong>Ready to send?</strong><p>To: {recipients(draft.to).join(', ')}</p>{#if draft.cc}<p>Cc: {recipients(draft.cc).join(', ')}</p>{/if}{#if draft.bcc}<p>Bcc: {recipients(draft.bcc).join(', ')}</p>{/if}<p>Subject: {draft.subject}</p>{#if draft.action}<p>{draft.action==='forward'?'Forward':draft.action==='replyAll'?'Reply all':'Reply'} to the selected original email. Original context is included.{draft.action==='forward'?' Original attachments are forwarded too.':' Original attachments are not reattached.'}</p>{/if}<button onclick={send}>Send email</button><button onclick={()=>review=false}>Keep editing</button></div>{:else}<footer><button class="primary" disabled={busy||draft.uncertain||!!invalid||!permitted} onclick={()=>review=true}>{busy?'Sending…':'Review & send'}</button>{#if invalid&&!draft.uncertain}<span class="send-guidance" role="status"><strong>Before sending</strong>{invalid}</span>{/if}<button disabled={busy} onclick={()=>confirmDiscard=true}>Discard draft</button></footer>{/if}
 {#if confirmDiscard}<div role="group" aria-label="Discard email draft"><p>Permanently discard this local draft?</p><button onclick={()=>onDiscard(draft.id)}>Discard permanently</button><button onclick={()=>confirmDiscard=false}>Keep draft</button></div>{/if}
</section>
<style>
.mail-compose{padding:24px clamp(20px,4vw,60px);overflow:auto;flex:1;min-height:0;color:var(--text-primary)}header{display:flex;align-items:center;justify-content:space-between;gap:20px}h2{font-size:25px;margin:10px 0}label{display:block;font-size:12px;color:var(--text-secondary);margin:12px 0}.address{display:flex;align-items:center;gap:14px}.address input{flex:1}input,textarea,select{box-sizing:border-box;background:var(--surface-base);color:var(--text-primary);border:1px solid var(--border-strong);border-radius:7px;padding:10px;font:inherit}label>input:not(.address input){display:block;width:100%;margin-top:8px}textarea{width:100%;min-height:240px;resize:vertical;font-size:14px;line-height:1.7}fieldset{border:0;padding:0;margin:0;min-width:0}fieldset:disabled{opacity:.7}button{padding:9px 12px;border:1px solid var(--border-strong);border-radius:7px;color:var(--accent);font-size:12px}button:disabled{opacity:.45;cursor:default}.primary{background:var(--accent);color:var(--text-on-accent)}footer{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-top:18px}.send-guidance{display:flex;flex-direction:column;gap:3px;border-left:3px solid var(--accent);background:var(--surface-panel);padding:9px 12px;font-size:13px;color:var(--text-primary);line-height:1.5}.send-guidance strong{color:var(--accent);font-size:11px}.note{font-size:11px;color:var(--text-secondary);line-height:1.7}.error{color:var(--error);font-size:13px}.uncertain,.review{border:1px solid var(--accent-border);padding:16px;border-radius:9px;margin:16px 0;line-height:1.7;font-size:13px;overflow-wrap:anywhere}.uncertain button{display:block;margin-top:12px}.review button{margin-right:10px}.lookup{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}.person{display:block;margin:6px 0}summary{font-size:12px;color:var(--accent);cursor:pointer}
</style>
